import { WORKER_EVIDENCE_KINDS } from '../mission/types.js';
import { DEFAULT_CONTEXT_BUDGET, clipList, clipText } from '../context/budget.js';
export function workerHandoffText(h, maxChars = DEFAULT_CONTEXT_BUDGET.max_handoff_chars) { return clipText(['Hi WORKER HANDOFF', 'Control plane: Hi. Do not become a top-level orchestrator.', `OBJECTIVE: ${clipText(h.objective, 4000)}`, `SCOPE: ${clipList(h.scope, 3000).join(', ') || 'bounded by objective'}`, `CONSTRAINTS: ${clipList(h.constraints, 4000).join(' | ') || 'minimum sufficient change'}`, `REQUIRED EVIDENCE: ${clipList(h.required_evidence, 3000).join(' | ') || 'none'}`, `RELEVANT CONTEXT: ${clipList(h.relevant_context, 5000).join(' | ') || 'none'}`, `HI METHODOLOGIES: ${h.methodologies.join(', ') || 'none'}`, `METHODOLOGY EXIT REQUIREMENTS: ${h.methodology_exit_requirements?.join(' | ') || 'none'}`, h.methodologies.length ? 'Load each listed methodology through the OpenCode native skill tool before applying it. Do not load unrelated skills.' : 'No methodology is selected; use native engineering judgment without loading unrelated skills.', h.approval_gated_methodologies?.length ? `APPROVAL-GATED METHODOLOGIES: ${h.approval_gated_methodologies.join(', ')}. Native OpenCode permission ask/deny remains authoritative.` : 'APPROVAL-GATED METHODOLOGIES: none.', 'Return compact JSON-compatible result with status, summary, changed_files, scope_expansions, evidence, open_issues, needs_context, context_gap, failure_finding. Use context_gap=scope|iterative|none and failure_finding=ci-build|unknown-root-cause|none only when directly supported by this bounded task. Evidence is structured proof, not prose classification: when a worker-scope methodology exit requires decision-evidence, diagnostic-evidence, measurement-evidence, browser-evidence, visual-evidence, accessibility-evidence, or source-provenance-evidence, return that exact evidence.kind with a concrete summary/scope; targeted-test-evidence may be satisfied by evidence.kind=targeted-tests. Do not rely on descriptive summary words to satisfy an exit. Optionally include methodology_observations only when this task produced a project-specific reusable HOW that is not already a selected methodology; each observation must contain key, procedure, trigger, do_not_trigger, exit_condition, evidence; observation.evidence must list exact evidence.kind values returned by this result, never summary fragments. Do not report project facts, one-off evidence, or control-plane policy as methodology observations. Use status DONE, FIX_REQUIRED, NEEDS_CONTEXT, BLOCKED, or FAILED. For every changed file outside SCOPE, include scope_expansions entry {file, necessary, reason}. Mark necessary=true only when the task cannot be correctly completed without that file; otherwise revert the collateral change before DONE.'].join('\n'), maxChars); }
const STATUS_ALIAS = { DONE: 'DONE', PASS: 'DONE', SUCCESS: 'DONE', SUCCEEDED: 'DONE', DONE_WITH_CONCERNS: 'DONE', FIX_REQUIRED: 'FIX_REQUIRED', NEEDS_CONTEXT: 'NEEDS_CONTEXT', USER_ACTION_REQUIRED: 'BLOCKED', BLOCKED: 'BLOCKED', NO_PROGRESS: 'FIX_REQUIRED', FAILED: 'FAILED', FAIL: 'FAILED' };
const WORKER_EVIDENCE_KIND_SET = new Set(WORKER_EVIDENCE_KINDS);
const EVIDENCE_OUTCOMES = new Set(['pending', 'passed', 'failed', 'environment-issue']);
function normalizeEvidence(raw) { const values = Array.isArray(raw) ? raw : (raw && typeof raw === 'object' ? Object.entries(raw).map(([kind, value]) => ({ kind, summary: typeof value === 'string' ? value : JSON.stringify(value) })) : []); return values.slice(0, 40).flatMap((v) => { if (!v || typeof v !== 'object')
    return []; const kind = String(v.kind ?? ''); if (!WORKER_EVIDENCE_KIND_SET.has(kind))
    return []; const outcome = typeof v.outcome === 'string' && EVIDENCE_OUTCOMES.has(v.outcome) ? v.outcome : undefined; return [{ kind, summary: clipText(String(v.summary ?? ''), 1000), scope: Array.isArray(v.scope) ? v.scope.map(String).slice(0, 50) : undefined, pass: typeof v.pass === 'boolean' ? v.pass : undefined, outcome, reason: typeof v.reason === 'string' ? v.reason : undefined }]; }); }
function normalizeMethodologyObservations(raw) { if (!Array.isArray(raw))
    return undefined; const out = raw.slice(0, 8).flatMap((v) => { if (!v || typeof v !== 'object')
    return []; const key = String(v.key ?? '').trim().toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/^-+|-+$/g, ''); const procedure = clipText(String(v.procedure ?? ''), 1600), trigger = clipText(String(v.trigger ?? ''), 600), doNotTrigger = clipText(String(v.do_not_trigger ?? ''), 600), exitCondition = clipText(String(v.exit_condition ?? ''), 600), evidence = Array.isArray(v.evidence) ? v.evidence.map(String).map((x) => clipText(x, 500)).filter((x) => WORKER_EVIDENCE_KIND_SET.has(x)).slice(0, 12) : []; if (!key || !procedure || !trigger || !doNotTrigger || !exitCondition || !evidence.length)
    return []; return [{ key, procedure, trigger, do_not_trigger: doNotTrigger, exit_condition: exitCondition, evidence }]; }); return out.length ? out : undefined; }
function evidenceFailed(e) { return e.outcome === 'failed' || e.pass === false; }
function evidencePassed(e) { return e.outcome === 'passed' || e.pass === true; }
function reconcileFailureFinding(finding, evidence) {
    if (finding === 'ci-build') {
        return evidence.some(e => e.kind === 'build' && evidenceFailed(e)) ? 'ci-build' : undefined;
    }
    if (finding === 'unknown-root-cause') {
        const provenRootCause = evidence.some(e => e.kind === 'diagnostic-evidence' && evidencePassed(e));
        return provenRootCause ? undefined : 'unknown-root-cause';
    }
    return finding;
}
export function normalizeWorkerResult(raw) { const x = (raw && typeof raw === 'object') ? raw : {}, status = STATUS_ALIAS[String(x.status ?? '').toUpperCase()] ?? 'FAILED'; const open = Array.isArray(x.open_issues) ? x.open_issues.map(String) : []; if (String(x.status ?? '').toUpperCase() === 'USER_ACTION_REQUIRED' && !open.some(v => v.includes('USER_ACTION_REQUIRED')))
    open.unshift('USER_ACTION_REQUIRED'); const contextGap = ['scope', 'iterative', 'none'].includes(String(x.context_gap)) ? String(x.context_gap) : undefined, rawFailureFinding = ['ci-build', 'unknown-root-cause', 'none'].includes(String(x.failure_finding)) ? String(x.failure_finding) : undefined, evidence = normalizeEvidence(x.evidence), failureFinding = reconcileFailureFinding(rawFailureFinding, evidence); return { status, summary: typeof x.summary === 'string' ? clipText(x.summary, 4000) : '', changed_files: Array.isArray(x.changed_files) ? x.changed_files.filter(v => typeof v === 'string').map(String).slice(0, 200) : [], scope_expansions: Array.isArray(x.scope_expansions) ? x.scope_expansions.filter(v => !!v && typeof v === 'object').slice(0, 80).map((v) => ({ file: String(v.file ?? ''), reason: clipText(String(v.reason ?? ''), 600), necessary: v.necessary === true })).filter(v => v.file) : [], evidence, open_issues: open.slice(0, 30), needs_context: Array.isArray(x.needs_context) ? x.needs_context.map(String).slice(0, 30) : [], context_gap: contextGap, failure_finding: failureFinding, methodology_observations: normalizeMethodologyObservations(x.methodology_observations) }; }
